/* frontend/src/components/Profile.js */
import React, { useState, useEffect } from 'react';

export default function Profile() {
  const [user, setUser] = useState(null);

  // Replace everything from Line 8 to Line 13 with this:
  useEffect(() => {
    const storedUser = localStorage.getItem('user');

    // Safety check to prevent crash if no one is logged in
    if (storedUser && storedUser !== "undefined") {
      setUser(JSON.parse(storedUser));
    } else {
      // Fallback data so the app doesn't show a red error screen
      setUser({
        fullName: "Guest User",
        email: "guest@vidyaquest.com",
        level: 1,
        xp: 0,
        nextXp: 500
      });
    }
  }, []);

  if (!user) return <div className="loading">Loading user profile...</div>;

  // Calculate XP percentage for the progress bar
  const progressPercent = user.nextXp > 0 ? (user.xp / user.nextXp) * 100 : 0;

 /* frontend/src/components/Profile.js */

  return (
    <div className="profile-page-wrapper">
      {/* 1. Profile Header Card */}
      <div className="profile-header-card">
        <div className="profile-banner-gradient"></div>
        <div className="profile-info-row">

          {/* DYNAMIC AVATAR: First letter of the MongoDB Name */}
          <div className="profile-avatar-large">
            <span className="avatar-icon">
              {user?.fullName ? user.fullName.charAt(0).toUpperCase() : 'U'}
            </span>
          </div>

          <div className="profile-user-details">
            {/* DYNAMIC NAME: Pulls directly from MongoDB */}
            <h1>{user?.fullName || "Guest User"}</h1>

            {/* DYNAMIC EMAIL: Pulls from MongoDB */}
            <p>VidyaQuest Learner • {user?.email || "guest@vidyaquest.com"}</p>
          </div>

          <div className="profile-actions">
            <button className="edit-btn">✏️ Edit Profile</button>
            <button className="signout-btn" onClick={() => { localStorage.clear(); window.location.reload(); }}>
              📤 Sign Out
            </button>
          </div>
        </div>
      </div>

      {/* Keep your dynamic Level Progress and Badges sections below this */}
    </div>
  );
}
